  if (runState === "idle") {
    const EmptyIcon = Icon[stage.icon];
    return (
      <section className="output-zone">
        <div className="output-empty">
          <div className="output-empty-icon">
            <EmptyIcon size={26} />
          </div>
          <div style={{ fontSize: 14, color: "var(--text-secondary)" }}>
