/* ============================================================
   Full Pipeline page — vertical stepper
   ============================================================ */
.fp-seed {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 24px;
  max-width: 560px;
}
.fp-seed-label {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.fp-seed-input {
  padding: 10px 14px;
  border-radius: var(--r-button);
  border: 1px solid var(--border);
  background: var(--bg-surface);
  color: var(--text-primary);
  font-size: 14px;
}
.fp-seed-input:focus { outline: none; border-color: var(--border-active); }
.fp-seed-input:disabled { opacity: 0.6; }

.fp-stepper {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.fp-step {
  border: 1px solid var(--border);
  border-left: 3px solid var(--stage-color);
  border-radius: var(--r-card);
  background: var(--bg-surface);
  padding: 16px 20px;
}
.fp-step.is-locked { opacity: 0.45; }
.fp-step.is-running { box-shadow: 0 0 0 1px color-mix(in oklab, var(--stage-color) 40%, transparent); }
.fp-step-head {
  display: flex;
  align-items: center;
  gap: 12px;
}
.fp-step-dot {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-size: 12px;
  font-weight: 600;
  color: var(--bg-base);
  background: var(--stage-color);
}
.fp-step.is-locked .fp-step-dot { background: var(--text-muted); }
.fp-step-label {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-primary);
}
.fp-step-status {
  margin-left: auto;
  font-size: 12px;
  color: var(--text-muted);
}
.fp-step-body { margin-top: 14px; }
.fp-step-summary {
  margin-top: 8px;
  font-size: 13px;
  color: var(--text-secondary);
  padding-left: 36px;
}

.fp-log {
  max-height: 220px;
  overflow: auto;
  background: var(--bg-base);
  border: 1px solid var(--border);
  border-radius: var(--r-button);
  padding: 12px 14px;
  font-family: var(--font-mono, monospace);
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-secondary);
  white-space: pre-wrap;
  margin: 0;
}

.fp-gate {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.fp-hint { font-size: 12px; color: var(--text-muted); }
.fp-trend-row {
  display: flex;
  gap: 10px;
  align-items: center;
}
.fp-trend-row .fp-seed-input { flex: 1; }

.fp-pick-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.fp-pick-card {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  text-align: left;
  width: 100%;
  padding: 12px 14px;
  border-radius: var(--r-button);
  border: 1px solid var(--border);
  background: var(--bg-base);
  color: var(--text-primary);
  cursor: pointer;
  transition: border-color 140ms ease, transform 180ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.fp-pick-card:hover {
  border-color: var(--stage-color);
  transform: translateX(3px);
}
.fp-pick-num {
  flex-shrink: 0;
  font-size: 12px;
  font-weight: 600;
  color: var(--stage-color);
}
.fp-pick-text { font-size: 14px; line-height: 1.4; }

.fp-error {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.fp-error-msg {
  font-size: 13px;
  color: #EF4444;
  background: color-mix(in oklab, #EF4444 10%, transparent);
  border: 1px solid color-mix(in oklab, #EF4444 30%, transparent);
  border-radius: var(--r-button);
  padding: 10px 12px;
}
.fp-done-banner {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-primary);
  margin-bottom: 12px;
}

