.fp-step-status {
  margin-left: auto;
  font-size: 12px;
  color: var(--text-muted);
}
.fp-step-body { margin-top: 14px; }
.fp-step-summary {
  margin-top: 8px;
  font-size: 13px;
  color: var(--text-secondary);
  padding-left: 36px;
}

.fp-log {
  max-height: 220px;
  overflow: auto;
  background: var(--bg-base);
  border: 1px solid var(--border);
  border-radius: var(--r-button);
  padding: 12px 14px;
  font-family: var(--font-mono, monospace);
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-secondary);
  white-space: pre-wrap;
  margin: 0;
}

.fp-gate {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.fp-hint { font-size: 12px; color: var(--text-muted); }
.fp-trend-row {
  display: flex;
  gap: 10px;
  align-items: center;
}
.fp-trend-row .fp-seed-input { flex: 1; }

.fp-pick-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.fp-pick-card {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  text-align: left;
  width: 100%;
  padding: 12px 14px;
  border-radius: var(--r-button);
  border: 1px solid var(--border);
  background: var(--bg-base);
  color: var(--text-primary);
  cursor: pointer;
  transition: border-color 140ms ease, transform 180ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.fp-pick-card:hover {
  border-color: var(--stage-color);
  transform: translateX(3px);
}
.fp-pick-num {
  flex-shrink: 0;
  font-size: 12px;
  font-weight: 600;
  color: var(--stage-color);
}
.fp-pick-text { font-size: 14px; line-height: 1.4; }

.fp-error {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.fp-error-msg {
  font-size: 13px;
  color: #EF4444;
  background: color-mix(in oklab, #EF4444 10%, transparent);
  border: 1px solid color-mix(in oklab, #EF4444 30%, transparent);
  border-radius: var(--r-button);
  padding: 10px 12px;
}
.fp-done-banner {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-primary);
  margin-bottom: 12px;
}

